        .quote-type.rich {
            background: var(--store-rush-soft);
            color: var(--universal-records-admin-orange);
        }

        .quote-type.emb {
            background: var(--sky-100);
            color: var(--universal-records-admin-cyan);
        }

        .quote-type.embc {
            background: var(--red-100);
            color: var(--universal-records-admin-red);
        }

        .quote-type.lt {
            background: var(--red-50);
