        }

        .quote-type.patch {
            background: var(--brand-100);
            color: var(--brand-600);
        }

        .quote-type.spc {
            background: var(--store-rush-soft);
            color: var(--universal-records-admin-orange-2);
        }

        .quote-type.ssc {
            background: var(--red-50);
