.bl-radio input { cursor: pointer; }

.bl-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 20px;
  border: none;
  border-radius: var(--bl-radius);
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s;
  white-space: nowrap;
}

.bl-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.bl-btn--primary {
  background: var(--bl-primary);
  color: white;
}

.bl-btn--primary:hover:not(:disabled) { background: var(--bl-primary-dark); }

.bl-btn--success {
  background: var(--bl-success);
  color: white;
}

.bl-btn--success:hover:not(:disabled) { background: var(--bl-success-dark); }

.bl-btn--danger {
  background: var(--bl-danger);
  color: white;
}

.bl-btn--small {
  padding: 6px 14px;
  font-size: 13px;
}

.bl-btn--large {
  padding: 12px 24px;
  font-size: 16px;
  min-height: 48px;
}

.bl-btn--xl {
  padding: 14px 28px;
  font-size: 18px;
  font-weight: 700;
  min-height: 56px;
  border-radius: 10px;
  box-shadow: var(--bl-shadow);
}

.bl-btn--outline {
  background: white;
  border: 2px solid var(--bl-gray-300);
  color: var(--bl-gray-700);
}

.bl-btn--outline:hover { border-color: var(--bl-primary); }

/* === ORDER BANNER === */
.bl-banner {
  background: white;
  border-bottom: 1px solid var(--bl-gray-200);
  padding: 10px 20px;
}

.bl-banner__row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 24px;
  padding: 2px 0;
}

.bl-banner__item {
  font-size: 15px;
  color: var(--bl-gray-700);
}

.bl-banner__item strong {
  color: var(--bl-gray-900);
}

/* Link Work Order bar */
.bl-banner__link-wo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 0 2px;
  border-top: 1px dashed var(--bl-warning);
  margin-top: 6px;
}

.bl-banner__link-wo-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--bl-warning);
}

/* === TOTALS BAR === */
.bl-totals {
  background: var(--bl-gray-800);
  color: white;
  padding: 10px 20px;
  display: flex;
  align-items: center;
  gap: 32px;
  font-size: 16px;
}

.bl-totals__item strong {
  font-size: 20px;
  margin: 0 2px;
}

.bl-totals__warning {
  background: var(--bl-warning);
  color: var(--bl-gray-900);
  padding: 4px 16px;
  border-radius: 20px;
  font-weight: 700;
  font-size: 14px;
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

/* === LOADING & ERROR === */
.bl-loading {
  text-align: center;
  padding: 80px 20px;
}

.bl-spinner {
  width: 48px;
  height: 48px;
  border: 4px solid var(--bl-gray-200);
  border-top-color: var(--bl-primary);
  border-radius: 50%;
  margin: 0 auto 16px;
  animation: spin 0.8s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

.bl-loading p { font-size: 18px; color: var(--bl-gray-500); }

.bl-error {
  background: var(--red-50);
  border: 2px solid var(--red-200);
  border-radius: var(--bl-radius);
  padding: 20px 24px;
  margin: 20px;
  display: flex;
  align-items: center;
  gap: 16px;
}

.bl-error p {
  font-size: 16px;
  color: var(--bl-danger);
  flex: 1;
}

/* === MAIN LAYOUT === */
.bl-main {
  display: flex;
  gap: 16px;
  padding: 16px 20px;
  min-height: calc(100vh - 200px);
}

.bl-column {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.bl-column--boxes {
  flex: 7;
  min-width: 0;
}

.bl-column--unboxed {
  flex: 3;
  min-width: 280px;
  max-width: 400px;
}

.bl-column__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 4px;
}

.bl-column__header h2 {
  font-size: 18px;
  font-weight: 700;
  color: var(--bl-gray-800);
}

.bl-column__actions {
  display: flex;
  gap: 8px;
}

/* === BOX CARDS === */
.bl-box-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.bl-box-card {
  background: white;
  border: 2px solid var(--bl-gray-200);
  border-radius: 10px;
  overflow: hidden;
  box-shadow: var(--bl-shadow);
  transition: border-color 0.15s;
}

.bl-box-card--verified {
  border-color: var(--bl-success);
}

.bl-box-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  cursor: pointer;
  user-select: none;
  transition: background 0.1s;
  min-height: 64px;
}

.bl-box-card__header:hover {
  background: var(--bl-gray-50);
}

.bl-box-card__title {
  display: flex;
  align-items: center;
  gap: 12px;
}

.bl-box-card__number {
  font-size: 22px;
  font-weight: 800;
  width: 44px;
  height: 44px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
}

.bl-box-card__info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.bl-box-card__label {
  font-size: 16px;
  font-weight: 700;
}

.bl-box-card__meta {
  font-size: 13px;
  color: var(--bl-gray-500);
  display: flex;
  gap: 12px;
}

.bl-box-card__tag {
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 10px;
  text-transform: uppercase;
}

.bl-box-card__tag--sanmar { background: var(--sky-100); color: var(--color-floor-dark); }
.bl-box-card__tag--custom { background: var(--amber-100); color: var(--amber-800); }

.bl-box-card__right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.bl-box-card__chevron {
  font-size: 20px;
  color: var(--bl-gray-400);
  transition: transform 0.2s;
}

.bl-box-card--expanded .bl-box-card__chevron {
  transform: rotate(180deg);
}

.bl-box-card__verify {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border: 2px solid var(--bl-gray-300);
  background: white;
  color: var(--bl-gray-600);
  transition: all 0.15s;
}

.bl-box-card__verify:hover {
  border-color: var(--bl-success);
}

.bl-box-card__verify--checked {
  background: var(--store-green-100);
  border-color: var(--bl-success);
  color: var(--bl-success-dark);
}

.bl-box-card__body {
  display: none;
  border-top: 1px solid var(--bl-gray-200);
  padding: 16px 18px;
}

.bl-box-card--expanded .bl-box-card__body {
  display: block;
}

/* Item cards inside boxes (draggable) */
.bl-item-card {
  background: var(--bl-gray-50);
  border: 2px solid var(--bl-gray-200);
  border-radius: 8px;
  padding: 12px 14px;
  margin-bottom: 10px;
  cursor: grab;
  transition: all 0.15s;
  min-height: 80px;
}

.bl-item-card:active { cursor: grabbing; }

.bl-item-card:hover {
  border-color: var(--bl-primary);
  box-shadow: var(--bl-shadow);
}

.bl-item-card__header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 8px;
}

.bl-item-card__style {
  font-size: 16px;
  font-weight: 700;
  color: var(--bl-gray-900);
}

.bl-item-card__color {
  font-size: 14px;
  color: var(--bl-gray-600);
}

.bl-item-card__qty {
  font-size: 18px;
  font-weight: 800;
  color: var(--bl-primary);
  white-space: nowrap;
}

.bl-item-card__desc {
  font-size: 13px;
  color: var(--bl-gray-500);
  margin-bottom: 8px;
}

/* Size grid inside item cards */
.bl-size-grid {
  display: flex;
  gap: 2px;
  flex-wrap: wrap;
}

.bl-size-cell {
  text-align: center;
  min-width: 48px;
  padding: 4px 6px;
  background: white;
  border: 1px solid var(--bl-gray-200);
  border-radius: 4px;
}

.bl-size-cell__label {
  font-size: 11px;
  color: var(--bl-gray-400);
  text-transform: uppercase;
  font-weight: 600;
}

.bl-size-cell__value {
  font-size: 18px;
  font-weight: 800;
  color: var(--bl-gray-900);
  cursor: pointer;
}

.bl-size-cell:hover {
  outline: 2px solid var(--bl-primary);
  outline-offset: -1px;
  border-radius: 4px;
}

/* Split button on item cards */
.bl-item-card__split {
  margin-top: 6px;
  /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
  font-size: 12px !important;
  /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
  padding: 4px 10px !important;
  opacity: 0.7;
}

.bl-item-card:hover .bl-item-card__split {
  opacity: 1;
}

.bl-size-cell--empty .bl-size-cell__value {
  color: var(--bl-gray-200);
}

.bl-size-cell--has-value {
  background: var(--color-floor-tint);
  border-color: var(--blue-200);
}

/* Box actions row */
.bl-box-card__actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--bl-gray-100);
}

/* Item list (droppable zone) */
.bl-item-list {
  min-height: 60px;
  padding: 4px;
  border-radius: 8px;
  transition: background 0.15s;
}

.bl-item-list--drag-over {
  background: var(--sky-100);
  border: 2px dashed var(--bl-primary);
}

/* === RIGHT COLUMN: UNBOXED === */
.bl-unboxed-container {
  flex: 1;
  overflow-y: auto;
}

.bl-section-label {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--bl-gray-500);
  letter-spacing: 0.5px;
  padding: 8px 4px 6px;
}

.bl-excluded-list {
  padding: 4px;
}

.bl-excluded-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background: var(--bl-gray-50);
  border: 1px solid var(--bl-gray-200);
  border-radius: 6px;
  margin-bottom: 6px;
  font-size: 14px;
  color: var(--bl-gray-500);
}

.bl-excluded-item__name {
  text-decoration: line-through;
}

/* Drop zone at bottom of right column */
.bl-drop-zone {
  border: 3px dashed var(--bl-gray-300);
  border-radius: 10px;
  padding: 24px;
  text-align: center;
  color: var(--bl-gray-400);
  font-size: 15px;
  font-weight: 600;
  margin-top: 12px;
  transition: all 0.15s;
}

.bl-drop-zone--active {
  border-color: var(--bl-danger);
  background: var(--red-50);
  color: var(--bl-danger);
}

/* Empty box placeholder */
.bl-box-empty {
  text-align: center;
  padding: 30px 20px;
  color: var(--bl-gray-400);
  font-size: 16px;
  border: 3px dashed var(--bl-gray-200);
  border-radius: 8px;
}

.bl-box-empty--drag-over {
  border-color: var(--bl-primary);
  background: var(--color-floor-tint);
  color: var(--bl-primary);
}

/* SortableJS ghost/drag styles */
.sortable-ghost {
  opacity: 0.4;
  /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
  background: var(--sky-100) !important;
  /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
  border-color: var(--bl-primary) !important;
}

.sortable-drag {
  /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
  box-shadow: var(--bl-shadow-lg) !important;
  transform: rotate(2deg);
}

.sortable-chosen {
  box-shadow: var(--bl-shadow-lg);
}

/* === MODAL === */
.bl-modal {
  position: fixed;
  inset: 0;
  background: rgb(0 0 0 / 50%);
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
}

.bl-modal__content {
  background: white;
  border-radius: 12px;
  padding: 28px;
  max-width: 500px;
  width: 90%;
  box-shadow: 0 20px 40px rgb(0 0 0 / 20%);
}

.bl-modal__content h3 {
  font-size: 20px;
  margin-bottom: 4px;
}

.bl-modal__content p {
  color: var(--bl-gray-500);
  margin-bottom: 20px;
}

.bl-split-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 8px;
  margin-bottom: 24px;
}

.bl-split-cell {
  text-align: center;
  padding: 8px;
  border: 1px solid var(--bl-gray-200);
  border-radius: 6px;
}

.bl-split-cell label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--bl-gray-500);
  margin-bottom: 4px;
}

.bl-split-cell__avail {
  font-size: 13px;
  color: var(--bl-gray-400);
  margin-bottom: 4px;
}

.bl-split-cell input {
  width: 60px;
  padding: 8px;
  text-align: center;
  font-size: 18px;
  font-weight: 700;
  border: 2px solid var(--bl-gray-300);
  border-radius: 6px;
}

.bl-split-cell input:focus {
  border-color: var(--bl-primary);
  outline: none;
}

.bl-modal__actions {
  display: flex;
  gap: 12px;
  justify-content: flex-end;
}

/* === UTILITIES === */
.bl-text-center { text-align: center; }
.bl-mt-2 { margin-top: 8px; }
.bl-mt-4 { margin-top: 16px; }

/* === RESPONSIVE === */
@media (width <= 1024px) {
  .bl-main {
    flex-direction: column;
  }

  .bl-column--unboxed {
    max-width: none;
  }

  .bl-header {
    flex-wrap: wrap;
  }

  .bl-header__search {
    flex-wrap: wrap;
  }
}

/* === ORDER GROUPS + REFERENCE (2026-08-04 rewrite: proxy label-data + shared template) === */
.bl-order { margin-bottom: 28px; }

.bl-order__head {
  display: flex; justify-content: space-between; align-items: flex-start; gap: 12px;
  border-left: 8px solid var(--gray-700); background: var(--color-surface); border-radius: 6px;
  padding: 10px 14px; margin-bottom: 10px; box-shadow: 0 1px 3px rgb(0 0 0 / 8%);
}
.bl-order__company { display: block; font-size: 18px; font-weight: 800; color: var(--print-ink); }
.bl-order__meta { display: block; font-size: 12.5px; color: var(--print-ink-soft); margin-top: 2px; }
.bl-order__flags { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }

.bl-rush-chip {
  display: inline-block; padding: 3px 8px; border-radius: 4px;
  font-size: 12.5px; font-weight: 800; letter-spacing: 0.02em;
  color: var(--color-on-brand); background: var(--red-700); border: 1px solid var(--print-red);
}
.bl-rush-chip--past { background: var(--print-red); }

.bl-follow-chip {
  display: inline-block; padding: 3px 8px; border-radius: 4px; font-size: 12px; font-weight: 700;
  color: var(--amber-800); background: var(--amber-100); border: 1px solid var(--box-labels-yellow);
}
.bl-received-chip { font-size: 12px; font-weight: 700; color: var(--green-600); }

.bl-nowo-chip {
  display: inline-block; padding: 2px 8px; border-radius: 4px; font-size: 12px; font-weight: 700;
  color: var(--box-labels-orange-2); background: var(--red-100); border: 1px dashed var(--store-rush-deep); cursor: help;
}

.bl-size-chip {
  display: inline-block; padding: 0 6px; margin-left: 4px; border-radius: 3px;
  font-size: 12px; font-weight: 800; color: var(--box-labels-blue); background: var(--sky-100);
}
.bl-ref { background: var(--color-surface); border: 1px solid var(--gray-200); border-radius: 6px; padding: 10px 12px; margin-bottom: 14px; }
.bl-ref__head { font-size: 13px; font-weight: 700; color: var(--box-labels-gray-dark); margin-bottom: 6px; }
.bl-ref__table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.bl-ref__table th, .bl-ref__table td { border-bottom: 1px solid var(--brand-100); padding: 4px 6px; text-align: left; }
.bl-ref__table th { color: var(--box-labels-gray); font-weight: 700; }
.bl-num { text-align: right; }

.bl-draft-note {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  margin: 12px 20px 0; padding: 10px 14px; border-radius: 6px;
  background: var(--color-floor-tint); border: 1px solid var(--box-labels-cyan); color: var(--box-labels-blue); font-size: 13.5px;
}
.bl-split-row { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; font-size: 15px; }
.bl-split-row label { font-weight: 700; min-width: 48px; }
.bl-split-row input[type="number"] { width: 80px; padding: 6px 8px; font-size: 16px; border: 2px solid var(--gray-300); border-radius: 6px; }
.bl-split-row select { padding: 6px 8px; font-size: 15px; border: 2px solid var(--gray-300); border-radius: 6px; }

/* Phone (≤640px) — 2026-09-05 staff-dashboard sweep: the page measured wider than the
   viewport at 375px and panned sideways. */
@media (width <= 640px) {
    .bl-header, .bl-header__right { flex-wrap: wrap; row-gap: 8px; }
    .bl-header__search { width: 100%; }
    #searchInput { min-width: 0; width: 100%; }
    #printAllBtn { white-space: normal; }
    .bl-back { color: inherit; text-decoration: none; font-weight: 600; font-size: 13px; }
}

.bl-back { color: inherit; text-decoration: none; font-weight: 600; font-size: 13px; opacity: .85; margin-right: 8px; }
.bl-back:hover { opacity: 1; text-decoration: underline; }
